import test from "node:test";
import assert from "node:assert/strict";
import { elementsFixture, layerVisible } from "./elements-harness.mjs";
import { MOTION_ELEMENTS, elementInsertError, elementTrack, elementTrackData, findElement } from "../../../packages/contracts/dist/index.js";

// `ae.elements.insert`: a pre-comp built from the recipe, with Essential
// Properties, expression timing that follows the pre-comp duration and an
// optional sound generated by Moti.on.
const inner = f => f.list.find(item => item.layersList && item !== f.comp);
const shapeContents = layer => layer.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group");

test("a lower third becomes a pre-comp at the current time with editable texts and colors", async () => {
  const f = await elementsFixture();
  const result = f.insert({ elementId: "lt-bar", texts: { title: "Ana Souza", subtitle: "Diretora" }, colors: { accent: [0, .5, 1] } });
  assert.equal(result.changed, true);
  const folder = f.list.find(item => item.name === "Moti.on Elementos");
  const precomp = inner(f);
  assert.equal(precomp.parentFolder, folder);
  assert.equal(precomp.name, "Moti.on · Barra clássica");
  assert.equal(precomp.duration, 120 / 30);
  assert.deepEqual(precomp.layersList.map(l => l.name), ["Subtítulo", "Título", "Caixa", "Barra", "Moti.on Cores", "whoosh.wav"]);
  assert.deepEqual(precomp.controllers.map(c => c.name), ["Título", "Subtítulo", "Cor principal", "Cor de destaque", "Cor do texto"]);
  assert.deepEqual(result.data.controllers, precomp.controllers.map(c => c.name));
  const title = precomp.layer("Título").property("ADBE Text Properties").property("ADBE Text Document").value;
  assert.equal(title.text, "Ana Souza"); assert.equal(title.font, "Arial-BoldMT"); assert.equal(title.fontSize, 46);
  assert.equal(precomp.layer("Subtítulo").property("ADBE Text Properties").property("ADBE Text Document").value.font, "ArialMT");
  assert.equal(precomp.layer("Moti.on Cores").guideLayer, true);
  // The accent control carries the chosen color and the bar reads it.
  const bar = shapeContents(precomp.layer("Barra")).property("ADBE Vector Graphic - Fill").property("ADBE Vector Fill Color");
  assert.deepEqual(bar.valueAtTime(1), [0, .5, 1, 1]);
  const parent = f.comp.layer(1);
  assert.equal(parent.source, precomp); assert.equal(parent.startTime, 2); assert.equal(parent.collapseTransformation, true);
  assert.deepEqual(f.comp.selectedLayers, [parent]);
  assert.match(parent.comment, /^\[MOTION_ELEMENT_V1\]\{"schemaVersion":1,"elementId":"lt-bar"/);
  assert.equal(f.comp.time, 2);
  assert.equal(f.imports, 1);
  assert.equal(result.data.sound, "whoosh");
});

test("boxes follow the measured text and grow from their left edge", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "lt-bar", texts: { title: "Ana" } });
  const precomp = inner(f), rect = shapeContents(precomp.layer("Caixa")).property("ADBE Vector Shape - Rect");
  const size = () => rect.property("ADBE Vector Rect Size").valueAtTime(2), position = () => rect.property("ADBE Vector Rect Position").valueAtTime(2);
  const short = size()[0];
  assert.ok(Math.abs(position()[0] - short / 2) < 1e-9, "left edge on the layer origin");
  const source = precomp.layer("Título").property("ADBE Text Properties").property("ADBE Text Document");
  source.setValue(Object.assign(source.value, { text: "Ana Clara Souza Mendes" }));
  assert.ok(size()[0] > short + 200);
  assert.ok(Math.abs(position()[0] - size()[0] / 2) < 1e-9);
  // The text anchor sits on its left middle, so the box and text share a baseline-free layout.
  const anchor = precomp.layer("Título").property("ADBE Transform Group").property("ADBE Anchor Point").valueAtTime(2);
  assert.equal(anchor[0], 0);
  assert.ok(Math.abs(anchor[1] - (-36.8 + (1.2 * 46 - 18.4) / 2)) < 1e-9);
});

test("every animated property evaluates the shared track math", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "title-pop", animationFrames: 20, durationFrames: 90 });
  const precomp = inner(f), spec = findElement("title-pop"), d = 3, a = 20 / 30;
  const title = precomp.layer("Título").property("ADBE Transform Group");
  const opacity = spec.layers[0].tracks.find(t => t.channel === "opacity"), scale = spec.layers[0].tracks.find(t => t.channel === "scale");
  for (const time of [0, .1, .3, .5, 1.5, 2.4, 2.7, 3]) {
    assert.ok(Math.abs(title.property("ADBE Opacity").valueAtTime(time) - elementTrack(time, d, a, elementTrackData(opacity.segments))) < 1e-9, `opacity ${time}`);
    const s = elementTrack(time, d, a, elementTrackData(scale.segments));
    assert.deepEqual(title.property("ADBE Scale").valueAtTime(time).map(v => Math.round(v * 1e6) / 1e6), [s, s].map(v => Math.round(v * 1e6) / 1e6));
  }
});

test("every element starts and ends hidden and shows at rest, with finite expressions", async () => {
  for (const element of MOTION_ELEMENTS) {
    const f = await elementsFixture();
    f.insert({ elementId: element.id, sound: "none" });
    const precomp = inner(f), d = precomp.duration;
    const drawn = precomp.layersList.filter(l => l.kind === "text" || l.kind === "shape");
    assert.equal(drawn.length, element.layers.length, element.id);
    for (const layer of drawn) for (const time of [0, d / 3, d / 2, d]) {
      for (const group of [layer.property("ADBE Transform Group")]) for (const p of group.children) {
        const v = p.valueAtTime(time);
        assert.ok([].concat(v).every(Number.isFinite), `${element.id} ${layer.name} ${p.matchName} @${time}`);
      }
    }
    if (element.timing === "in-out") assert.ok(drawn.every(l => !layerVisible(l, 0)), `${element.id} hidden at the start`);
    assert.ok(drawn.every(l => !layerVisible(l, d)), `${element.id} hidden at the end`);
    const rest = element.timing === "in-out" ? d / 2 : d * .45;
    assert.ok(drawn.some(l => layerVisible(l, rest)), `${element.id} visible at rest`);
  }
});

test("the exit follows the pre-comp duration without moving keys", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "check", sound: "none" });
  const precomp = inner(f), disc = precomp.layer("Disco");
  assert.equal(layerVisible(disc, 1.5), true);
  precomp.duration = 6;
  assert.equal(layerVisible(disc, 5.99), true, "rest extends with the duration");
  assert.equal(layerVisible(disc, 6), false, "exit ends on the new end");
});

test("shapes use native operators: repeater copies, round caps and stroke width scaled", async () => {
  const f = await elementsFixture({ width: 3840, height: 2160 });
  f.insert({ elementId: "burst", size: 50, sound: "none" });
  const rays = shapeContents(inner(f).layer("Raios"));
  assert.deepEqual(rays.children.map(c => c.matchName), ["ADBE Vector Shape - Group", "ADBE Vector Filter - Trim", "ADBE Vector Graphic - Stroke", "ADBE Vector Filter - Repeater"]);
  const repeater = rays.property("ADBE Vector Filter - Repeater");
  assert.equal(repeater.property("ADBE Vector Repeater Copies").value, 8);
  assert.deepEqual(repeater.property("ADBE Vector Repeater Transform").property("ADBE Vector Repeater Position").value, [0, 0]);
  assert.equal(repeater.property("ADBE Vector Repeater Transform").property("ADBE Vector Repeater Rotation").value, 45);
  const stroke = rays.property("ADBE Vector Graphic - Stroke");
  assert.equal(stroke.property("ADBE Vector Stroke Line Cap").value, 2);
  assert.equal(stroke.property("ADBE Vector Stroke Width").value, 10, "2x comp at 50%");
  assert.deepEqual(rays.property("ADBE Vector Shape - Group").property("ADBE Vector Shape").value.vertices, [[0, -70], [0, -150]]);
  assert.deepEqual(inner(f).layer("Faíscas").property("ADBE Transform Group").property("ADBE Rotate Z").value, 22.5);
});

test("sounds are imported once into the elements folder and can be turned off", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "check" });
  f.insert({ elementId: "lt-tag" });
  assert.equal(f.imports, 1, "pop reused");
  const sounds = f.list.find(item => item.name === "Sons");
  assert.equal(sounds.parentFolder.name, "Moti.on Elementos");
  assert.equal(f.list.filter(item => item.name === "Moti.on Elementos").length, 1);
  f.insert({ elementId: "ring", sound: "none" });
  const last = f.comp.layer(1).source;
  assert.equal(last.layersList.some(l => l.kind === "av"), false);
  f.insert({ elementId: "ring", sound: "chime" });
  assert.equal(f.imports, 2);
  assert.equal(f.comp.layer(1).source.name, "Moti.on · Anel expansivo 2");
});

test("a failure leaves the project as it was", async () => {
  const f = await elementsFixture({ exposeFails: true });
  const before = f.list.length;
  assert.equal(f.command.preflight({ elementId: "lt-line" }, { locale: "pt-BR" }), null);
  assert.throws(() => f.command.run({ elementId: "lt-line" }, { locale: "pt-BR" }), /Propriedades essenciais/);
  assert.equal(f.list.length, before, "no comp, folder, solid or footage left");
  assert.deepEqual(f.comp.layersList, [f.user]);
  assert.deepEqual(f.comp.selectedLayers, [f.user]);
});

test("capabilities are checked before anything changes", async () => {
  const missing = await elementsFixture({ missingSounds: ["whoosh"] });
  assert.equal(missing.command.preflight({ elementId: "arrow" }, {}).code, "CAPABILITY_UNAVAILABLE");
  assert.equal(missing.command.preflight({ elementId: "arrow", sound: "none" }, {}), null);
  const old = await elementsFixture({ essential: false }), before = old.list.length;
  assert.equal(old.command.preflight({ elementId: "arrow", sound: "none" }, {}).code, "CAPABILITY_UNAVAILABLE");
  assert.equal(old.list.length, before);
});

test("host validation matches the contract field by field", async () => {
  const f = await elementsFixture();
  const cases = [
    { elementId: "nope" }, { elementId: "lt-bar", extra: 1 }, { elementId: "lt-bar", durationFrames: 5 }, { elementId: "lt-bar", durationFrames: 20.5 },
    { elementId: "lt-bar", animationFrames: 1 }, { elementId: "lt-bar", durationFrames: 30, animationFrames: 16 }, { elementId: "burst", durationFrames: 12, animationFrames: 40 },
    { elementId: "lt-bar", size: 10 }, { elementId: "lt-bar", sound: "boom" }, { elementId: "lt-bar", colors: { primary: [1, 1] } },
    { elementId: "lt-bar", colors: { glow: [1, 1, 1] } }, { elementId: "lt-bar", colors: { text: [1, 2, 0] } }, { elementId: "lt-bar", texts: { title: "a\u0007b" } },
    { elementId: "lt-bar", texts: { title: "x".repeat(121) } }, { elementId: "title-pop", texts: { subtitle: "não existe" } }, { elementId: "lt-bar", texts: { title: "Linha 1\nLinha 2" } },
    { elementId: "check", durationFrames: 1800, animationFrames: 120, size: 400, sound: "click", colors: { primary: [0, 0, 0] } }
  ];
  for (const args of cases) {
    const expected = elementInsertError(args), error = f.command.preflight(args, {});
    assert.equal(error?.details?.field ?? null, expected, JSON.stringify(args));
    if (expected) assert.equal(error.code, "INVALID_PRESET");
  }
});

test("English sessions get English names and default texts", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "title-rise", sound: "none" }, "en-US");
  const precomp = inner(f);
  assert.equal(f.list.find(item => item.comment === "[MOTION_ELEMENTS_FOLDER]").name, "Moti.on Elements");
  assert.equal(precomp.name, "Moti.on · Rising title");
  assert.deepEqual(precomp.controllers.map(c => c.name), ["Title", "Subtitle", "Main color", "Accent color", "Text color"]);
  assert.equal(precomp.layer("Title").property("ADBE Text Properties").property("ADBE Text Document").value.text, "Big idea");
});

test("a missing Arial keeps the default font and warns once", async () => {
  const f = await elementsFixture({ fonts: ["ArialMT"] });
  const result = f.insert({ elementId: "title-rise", sound: "none" });
  assert.equal(result.warnings.length, 1);
  assert.equal(result.warnings[0].code, "elements.fontFallback");
  assert.equal(inner(f).layer("Título").property("ADBE Text Properties").property("ADBE Text Document").value.font, "SlowlyMove");
  assert.equal(inner(f).layer("Subtítulo").property("ADBE Text Properties").property("ADBE Text Document").value.font, "ArialMT");
});

test("a counter drives its text from the published Start and End sliders, in the session language", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "stat-count", sound: "none" });
  const precomp = inner(f), d = precomp.duration;
  // The counter text is not a typed role: only the caption, colors and the two sliders are published.
  assert.deepEqual(precomp.controllers.map(c => c.name), ["Subtítulo", "Cor principal", "Cor de destaque", "Cor do texto", "Início", "Fim"]);
  const source = precomp.layer("Título").property("ADBE Text Properties").property("ADBE Text Document");
  assert.equal(source.valueAtTime(0), "0+");
  assert.equal(source.valueAtTime(d * .8), "1.000+");
  assert.equal(source.valueAtTime(d), "1.000+");
  const end = precomp.layer("Moti.on Cores").property("ADBE Effect Parade").property("Fim").property("ADBE Slider Control-0001");
  assert.equal(end.value, 1000);
  end.setValue(25000);
  assert.equal(source.valueAtTime(d), "25.000+", "editing End in Essential Properties changes the count");
});

test("an English clock counts down in real seconds with English slider names", async () => {
  const f = await elementsFixture();
  f.insert({ elementId: "countdown-ring", sound: "none" }, "en-US");
  const precomp = inner(f);
  assert.deepEqual(precomp.controllers.map(c => c.name).slice(-2), ["Start", "End"]);
  const source = precomp.layer("Title").property("ADBE Text Properties").property("ADBE Text Document");
  assert.equal(source.valueAtTime(0), "00:10");
  assert.equal(source.valueAtTime(3), "00:07");
  assert.equal(source.valueAtTime(precomp.duration), "00:00");
});
